use std::fs
use std::env
use std::process

fn emit(text: string, num: bool, counter: int) -> int {
    let mut c = counter
    if num {
        for line in text.lines() {
            c = c + 1
            println("${c:>6}\t${line}")
        }
    } else {
        print(text)
    }
    c
}

fn main() {
    let mut num = false
    let mut names: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
        } else if a == "-n" {
            num = true
        } else {
            names.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if names.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, num, counter)
    } else {
        for n in names {
            match fs::read_to_string(n) {
                Ok(t) => {
                    counter = emit(t, num, counter)
                }
                Err(_) => {
                    println("cat: ${n}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        process::exit(status)
    }
}
